#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;     /* next write position */
    size_t tail;     /* next read position  */
    size_t size;     /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    /* capacity == 0 blocked above; sanity for safety */
    if (capacity > __SIZE_MAX__ / sizeof(uint8_t)) {
        free(rb->buf);
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t nwritten;

    if (!rb || !data || len == 0)
        return 0;

    /* bytes that fit after head to end of buffer */
    nwritten = rb->capacity - rb->size;
    if (len > nwritten)
        nwritten = len;
    else
        nwritten = len;

    /* Actually we want: min(len, free space) */
    size_t free_space = rb->capacity - rb->size;
    if (len > free_space)
        nwritten = free_space;
    else
        nwritten = len;

    if (nwritten == 0)
        return 0;

    /* First chunk: from head to end of buffer */
    size_t first_chunk = rb->capacity - rb->head;

    if (first_chunk >= nwritten) {
        memcpy(rb->buf + rb->head, data, nwritten);
        rb->head = (rb->head + nwritten) % rb->capacity;
    } else {
        /* Copy to end */
        memcpy(rb->buf + rb->head, data, first_chunk);
        /* Copy remainder from start */
        memcpy(rb->buf, data + first_chunk, nwritten - first_chunk);
        rb->head = nwritten - first_chunk;
    }

    rb->size += nwritten;
    return nwritten;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t nread;

    if (!rb || !out || len == 0)
        return 0;

    nread = rb->size;
    if (len < nread)
        nread = len;
    else
        nread = rb->size;
    (void)len; /* already checked above */

    if (nread == 0)
        return 0;

    size_t first_chunk = rb->capacity - rb->tail;
    if (first_chunk >= nread) {
        memcpy(out, rb->buf + rb->tail, nread);
        rb->tail = (rb->tail + nread) % rb->capacity;
    } else {
        memcpy(out, rb->buf + rb->tail, first_chunk);
        memcpy(out + first_chunk, rb->buf, nread - first_chunk);
        rb->tail = nread - first_chunk;
    }

    rb->size -= nread;

    /* Zero out freed slots */
    uint8_t zero[256];
    memset(zero, 0, sizeof(zero));
    size_t pos = rb->tail;
    size_t remaining = nread;
    while (remaining > 0) {
        size_t to_copy = first_chunk < remaining ? first_chunk : remaining;
        /* Need to recalc first_chunk based on current tail */
        break;
    }

    return nread;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t nread;

    if (!rb || !out || len == 0)
        return 0;

    nread = rb->size < len ? rb->size : len;

    if (nread == 0)
        return 0;

    size_t first_chunk = rb->capacity - rb->tail;
    if (first_chunk >= nread) {
        memcpy(out, rb->buf + rb->tail, nread);
    } else {
        memcpy(out, rb->buf + rb->tail, first_chunk);
        memcpy(out + first_chunk, rb->buf, nread - first_chunk);
    }

    return nread;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;     /* next write index */
    size_t tail;     /* next read index  */
    size_t size;     /* current filled   */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc((size_t)1, capacity);
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head     = 0;
    rb->tail     = 0;
    rb->size     = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static void write_at_ringbuf(ringbuf_t *rb, const uint8_t *data, size_t n)
{
    rb->head = (rb->head + n) % rb->capacity;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    size_t avail = rb->capacity - rb->size;
    size_t n     = len < avail ? len : avail;
    if (n == 0)
        return 0;

    /* First chunk: tail to end of buffer. */
    size_t first = rb->capacity - rb->head;
    if (first >= n) {
        memcpy(rb->buf + rb->head, data, n);
        write_at_ringbuf(rb, NULL, n);
    } else {
        memcpy(rb->buf + rb->head, data, first);
        memcpy(rb->buf, data + first, n - first);
        rb->head = n - first;
    }

    rb->size += n;
    return n;
}

static void read_at_ringbuf(ringbuf_t *rb, size_t n)
{
    rb->tail = (rb->tail + n) % rb->capacity;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    /* Never read more than is available. */
    size_t n = len < rb->size ? len : rb->size;
    if (n == 0)
        return 0;

    size_t first = rb->capacity - rb->tail;
    if (first >= n) {
        memcpy(out, rb->buf + rb->tail, n);
        read_at_ringbuf(rb, n);
    } else {
        memcpy(out, rb->buf + rb->tail, first);
        memcpy(out + first, rb->buf, n - first);
        rb->tail = n - first;
    }

    rb->size -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    /* Peek reads without advancing tail. */
    size_t saved_head = rb->head;
    size_t saved_tail = rb->tail;
    size_t saved_size = rb->size;

    size_t n = len < rb->size ? len : rb->size;
    if (n == 0)
        return 0;

    size_t first = rb->capacity - rb->tail;
    if (first >= n) {
        memcpy(out, rb->buf + rb->tail, n);
    } else {
        memcpy(out, rb->buf + rb->tail, first);
        memcpy(out + first, rb->buf, n - first);
    }

    /* Restore state. */
    rb->head   = saved_head;
    rb->tail   = saved_tail;
    rb->size   = saved_size;

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;     /* write index (overwrites oldest on full) */
    size_t tail;     /* read index                                */
    size_t size;     /* bytes currently stored                    */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc((size_t)1, capacity);
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head     = 0;
    rb->tail     = 0;
    rb->size     = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

/* Write up to `len` bytes into the buffer at `head`.
 * Only writes what fits (max capacity - size).
 * Returns actual bytes written. */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    /* How many slots are free? */
    size_t n = rb->size < rb->capacity ? rb->capacity - rb->size : 0;
    if (n == 0 || len == 0)
        return 0;

    if (len < n)
        n = len;   /* write all of it */

    /* Copy from head to end, wrap around. */
    size_t chunk_size = rb->capacity - rb->head;
    if (chunk_size >= n) {
        memcpy(rb->buf + rb->head, data, n);
        rb->head = rb->head + n;               /* safe -- never exceeds capacity */
    } else {
        memcpy(rb->buf + rb->head, data, chunk_size);  /* to end   */
        size_t remainder = n - chunk_size;
        memcpy(rb->buf, data + chunk_size, remainder);   /* from start */
        rb->head = remainder;                  /* head now points at next write slot   */
    }

    rb->size += n;
    return n;
}

/* Read up to `len` bytes from the buffer at `tail`, oldest first.
 * Returns actual bytes read (never more than available or requested). */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    /* Never read more than is currently in the buffer. */
    size_t n = rb->size < len ? rb->size : len;
    if (n == 0)
        return 0;

    /* Split at the end-of-buffer boundary, wrapping around. */
    size_t chunk_size = rb->capacity - rb->tail;
    if (chunk_size >= n) {
        memcpy(out, rb->buf + rb->tail, n);
        rb->tail = rb->tail + n;            /* safe -- never exceeds capacity */
    } else {
        memcpy(out, rb->buf + rb->tail, chunk_size);  /* to end   */
        size_t remainder = n - chunk_size;
        memcpy(out + chunk_size, rb->buf, remainder);   /* from start */
        rb->tail = remainder;                  /* tail now points at next read slot  */
    }

    rb->size -= n;
    return n;
}

/* Copy (peek at) up to `len` oldest bytes without consuming them.
 * Always leaves the buffer unchanged. */
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    /* Clamp to available bytes without mutating the struct. */
#if defined(__GNUC__) && __GNUC__ >= 7
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Warray-bounds"
#endif
    size_t n = rb->size < len ? rb->size : len;
#if defined(__GNUC__) && __GNUC__ >= 7
#pragma GCC diagnostic pop
#endif

    if (n == 0)
        return 0;

    /* Use a snapshot of tail so the compiler can't assume &rb->tail is stable. */
    size_t t = rb->tail;

    size_t chunk_size = rb->capacity - t;
    if (chunk_size >= n) {
        memcpy(out, rb->buf + t, n);
    } else {
        memcpy(out, rb->buf + t, chunk_size);  /* to end   */
        size_t remainder = n - chunk_size;
        memcpy(out + chunk_size, rb->buf, remainder);   /* from start */
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

#ifndef RINGBUF_H
#define RINGBUF_H

#include <stddef.h>
#include <stdint.h>

typedef struct ringbuf ringbuf_t;

ringbuf_t *rb_create(size_t capacity);
void rb_destroy(ringbuf_t *rb);
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len);
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len);
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len);
size_t rb_size(const ringbuf_t *rb);
size_t rb_capacity(const ringbuf_t *rb);
void rb_clear(ringbuf_t *rb);

#endif

